/* Fuiet Script Node · inline asset references v1
 *
 * Keeps Script-node asset references readable: every character / scene / prop
 * used by a shot is referenced directly inside the natural-language visual
 * description with its exact @asset name. Dialogue speaker names use the same
 * @asset convention. No media is generated by this module.
 */
(()=>{
'use strict';
if(globalThis.FuietScriptInlineAssetRefs?.installed)return;

const VERSION='20260904-script-inline-assets-1';
const baseFetch=globalThis.fetch?.bind(globalThis);
if(typeof baseFetch!=='function')return;

const trackedBreakdownTasks=new Set();
const text=v=>String(v??'').trim();
const arr=v=>Array.isArray(v)?v:[];

const INLINE_RULES=`
[Fuiet 镜头资产直接引用规则]
这是强制输出规则：
1. assets.characters / assets.scenes / assets.props 中的 name 保持纯资产名称，不加 @。
2. 每个 shot.action 必须把该镜头实际使用的角色、场景、道具直接嵌入画面描述，使用精确的 @资产名。
3. 不要把 @资产名单独堆在句首、句尾，也不要输出“资产：@A @B @C”这种清单；@引用必须成为正常中文句子的一部分。
4. scene、characters、props 字段里列出的资产，只要在本镜可见或参与动作，就必须在 action 中出现对应的 @资产名；反过来，不在画面里的资产不要放进这些字段。
5. dialogue 中有明确说话人时，必须写成“@角色名：原台词”；旁白保持“旁白：原文”。不要改写原台词。
6. action 仍遵守起点 → 主要动作 → 终点，但每一段都直接使用 @角色 / @场景 / @道具。

正确示例：
action: "起点：镜头从@火锅店门口的@告示纸开始，@林晓站在门内；主要动作：@王胖子推门进入，@林晓抬头看向他；终点：两人在@火锅店内形成第一次对视。"
dialogue: "@林晓：胖子！把今天的差评再切一份，我尝尝。"

错误示例：
action: "@火锅店门口 @告示纸 @林晓 @王胖子，镜头展示店门口。"
错误原因：只是堆资产，没有把资产直接写进画面动作和空间关系。
`;

function requestUrl(input){return typeof input==='string'?input:String(input?.url||'')}
function methodOf(input,init={}){return String(init.method||input?.method||'GET').toUpperCase()}
function pathnameOf(input){try{return new URL(requestUrl(input),location.href).pathname}catch{return requestUrl(input).split('?')[0]}}
async function requestBodyJson(input,init={}){
  const raw=init.body;
  if(typeof raw==='string'){try{return JSON.parse(raw)}catch{return null}}
  if(raw&&typeof raw==='object'&&!(typeof FormData!=='undefined'&&raw instanceof FormData))return raw;
  if(typeof Request!=='undefined'&&input instanceof Request){try{return await input.clone().json()}catch{}}
  return null;
}
function withJsonBody(init={},body){
  const headers=new Headers(init.headers||{});
  if(!headers.has('content-type'))headers.set('content-type','application/json');
  return{...init,headers,body:JSON.stringify(body)};
}
function responseWithJson(res,body){
  const headers=new Headers(res.headers);headers.set('content-type','application/json; charset=utf-8');headers.set('cache-control','no-store');
  return new Response(JSON.stringify(body),{status:res.status,statusText:res.statusText,headers});
}
function escapeRegExp(v){return String(v).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function splitNames(v){
  if(Array.isArray(v))return v.map(text).filter(Boolean);
  return text(v).split(/[、,，/|]/).map(text).filter(Boolean);
}
function uniqueNames(values){return [...new Set(values.map(text).filter(Boolean))]}
function assetNames(obj){
  const a=obj?.assets||{};
  const read=list=>arr(list).map(x=>text(typeof x==='string'?x:(x?.name||x?.title))).filter(Boolean);
  return uniqueNames([...read(a.characters||a.roles),...read(a.scenes),...read(a.props||a.objects)]).sort((a,b)=>b.length-a.length);
}
function tagKnownNames(value,names){
  let out=text(value);if(!out)return out;
  for(const name of names){
    if(!name)continue;
    const re=new RegExp(`(^|[^@])${escapeRegExp(name)}`,'g');
    out=out.replace(re,(m,prefix)=>`${prefix}@${name}`);
  }
  return out.replace(/@@+/g,'@');
}
function shotNames(shot,catalog){
  const wanted=uniqueNames([text(shot?.scene),...splitNames(shot?.characters),...splitNames(shot?.props)]);
  return wanted.filter(name=>catalog.includes(name));
}
function ensureActionReferences(shot,catalog){
  let action=tagKnownNames(shot?.action||shot?.visual||shot?.description||'',catalog);
  const scene=text(shot?.scene),characters=splitNames(shot?.characters).filter(x=>catalog.includes(x)),props=splitNames(shot?.props).filter(x=>catalog.includes(x));
  const required=shotNames(shot,catalog),missing=required.filter(name=>!action.includes('@'+name));
  if(!missing.length)return action;

  // Neutral recovery only. It establishes who/where/what is visible without
  // inventing a new plot action, then keeps the model-authored description.
  const missingScene=scene&&missing.includes(scene)?scene:'';
  const missingChars=characters.filter(x=>missing.includes(x));
  const missingProps=props.filter(x=>missing.includes(x));
  const clauses=[];
  if(missingChars.length&&missingScene)clauses.push(`${missingChars.map(x=>'@'+x).join('、')}位于@${missingScene}`);
  else{
    if(missingScene)clauses.push(`画面位于@${missingScene}`);
    if(missingChars.length)clauses.push(`${missingChars.map(x=>'@'+x).join('、')}出现在画面中`);
  }
  if(missingProps.length)clauses.push(`画面中可见${missingProps.map(x=>'@'+x).join('、')}`);
  const prefix=clauses.join('，');
  return [prefix,action].filter(Boolean).join(prefix&&action?'；':'');
}
function normalizeBreakdownObject(input){
  if(!input||typeof input!=='object'||!Array.isArray(input.shots))return input;
  const obj=JSON.parse(JSON.stringify(input)),catalog=assetNames(obj);
  obj.shots=obj.shots.map(shot=>{
    const next={...shot};
    next.action=ensureActionReferences(next,catalog);
    next.dialogue=tagKnownNames(next.dialogue||next.voice||'',catalog);
    if(next.imagePrompt)next.imagePrompt=tagKnownNames(next.imagePrompt,catalog);
    if(next.videoPrompt)next.videoPrompt=tagKnownNames(next.videoPrompt,catalog);
    return next;
  });
  return obj;
}
function extractJson(raw){
  const s=text(raw);if(!s)return null;
  const fenced=[...s.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)].map(m=>m[1]);
  for(const candidate of [...fenced,s]){
    try{return JSON.parse(candidate)}catch{}
    const a=candidate.indexOf('{'),b=candidate.lastIndexOf('}');if(a>=0&&b>a){try{return JSON.parse(candidate.slice(a,b+1))}catch{}}
  }
  return null;
}
function rewriteTaskOutput(task){
  if(!task||task.status!=='succeeded'||!task.output)return false;
  const keys=['value','text','url'];
  for(const key of keys){
    if(typeof task.output[key]!=='string')continue;
    const parsed=extractJson(task.output[key]);if(!parsed||!Array.isArray(parsed.shots))continue;
    const normalized=normalizeBreakdownObject(parsed);
    task.output[key]=JSON.stringify(normalized);
    return true;
  }
  return false;
}

async function intercept(input,init={}){
  const path=pathnameOf(input),method=methodOf(input,init);

  if(method==='POST'&&/\/api\/tasks\/?$/.test(path)){
    const body=await requestBodyJson(input,init);
    const op=String(body?.parameters?.operation||'');
    let nextInit=init;
    if(body&&op==='script_breakdown'){
      body.prompt=`${INLINE_RULES}\n\n${String(body.prompt||'')}`;
      body.parameters={...(body.parameters||{}),inlineAssetRefs:VERSION};
      nextInit=withJsonBody(init,body);
    }
    const res=await baseFetch(input,nextInit);
    if(body&&op==='script_breakdown'){
      try{const json=await res.clone().json(),id=String(json?.task?.id||json?.id||'');if(id)trackedBreakdownTasks.add(id)}catch{}
    }
    return res;
  }

  const match=path.match(/\/api\/tasks\/([^/?]+)\/?$/);
  if(method==='GET'&&match&&trackedBreakdownTasks.has(decodeURIComponent(match[1]))){
    const res=await baseFetch(input,init);if(!res.ok)return res;
    try{
      const body=await res.clone().json(),task=body?.task||body;
      if(rewriteTaskOutput(task))return responseWithJson(res,body);
      return res;
    }catch{return res}
  }

  return baseFetch(input,init);
}

globalThis.fetch=intercept;
globalThis.FuietScriptInlineAssetRefs=Object.freeze({installed:true,version:VERSION,rules:INLINE_RULES,normalizeBreakdownObject,ensureActionReferences,tagKnownNames});
})();
